  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Read the echo pin and calculate the duration of the pulse
  duration = pulseIn(echoPin, HIGH);

  // Convert duration to distance in centimeters
